#!/usr/bin/env bash
# Outer loop for long unattended runs: one fresh Claude Code session per task.
# Generated by `tp init --claude`; edit freely.
set -euo pipefail
MAX_ITER=${MAX_ITER:-50}
# Scope the run to one milestone on its branch: PARENT=M-0002 scripts/tp-loop.sh
PARENT=${PARENT:?set PARENT to a tp milestone id, e.g. PARENT=M-0002}
branch=$(git branch --show-current)
if [[ "$branch" == "main" || -z "$branch" ]]; then
  echo "Refusing to run on '${branch:-detached HEAD}': switch to the milestone branch first." >&2
  exit 1
fi
for i in $(seq 1 "$MAX_ITER"); do
  tp next --parent "$PARENT" --json >/dev/null 2>&1 || { echo "No ready tasks. Done."; break; }
  echo "iteration $i" >&2
  claude -p "Run 'tp status' and 'tp next --parent $PARENT'. Complete exactly that one task following the taskplan skill: start it, implement, make its verify pass, 'tp done --commit-head', then stop." \
    --permission-mode auto --output-format json >> .plan/loop.log
done
tp export board --no-notes --no-timestamp -o TODO.md
